import csv, io

def average_price(text):
    reader = csv.DictReader(io.StringIO(text))
    total = 0.0
    count = 0
    for row in reader:
        price = row["price"].strip()
        if price == "":
            continue
        total += float(price)
        count += 1
    if count == 0:
        return 0.0
    return round(total / count, 2)
